(7679286, 1256133, 65234, '<td valign="top">The crow is a nice touch. Very well done.</td>', 'The crow is a nice touch. Very well done.', '2020-11-11 08:33:54.000000', NULL, 1),
(7679287, 1256143, 65234, '<td valign="top">I''m really bad at this; I''m only seeing two very creepy dolls (one whole doll and one head). And I''m going to get a headache if I stare at this any longer! Minor nit: looks like an offset layer over there on the right but I can''t tell if it''s intentional.</td>', 'I''m really bad at this; I''m only seeing two very creepy dolls (one whole doll and one head). And I''m going to get a headache if I stare at this any longer! Minor nit: looks like an offset layer over there on the right but I can''t tell if it''s intentional.', '2020-11-11 08:42:03.000000', NULL, 1),
(7679289, 1255977, 65234, '<td valign="top">I like that there''s another apparition in the back on the left. Just a nice detail.</td>', 'I like that there''s another apparition in the back on the left. Just a nice detail.', '2020-11-11 08:43:25.000000', NULL, 1),
(7679292, 1255949, 65234, '<td valign="top">Nice. In a disgusting, creepy sort of way. The atmospheric lighting works well.</td>', 'Nice. In a disgusting, creepy sort of way. The atmospheric lighting works well.', '2020-11-11 08:44:21.000000', NULL, 1),
